import{_ as l,a0 as d,w as p,s as o,I as e,x as a,a1 as n,A as t,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如何在 Linux 中擴展 Veritas 文件系統（VxFS） | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中擴展 Veritas 文件系統（VxFS） | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中擴展 Veritas 文件系統（VxFS） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中擴展 Veritas 文件系統（VxFS） | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20230816 How to Extend Veritas File System (VxFS) in Linux","title":"如何在 Linux 中擴展 Veritas 文件系統（VxFS）","tag":"202309","desc":""},"relativePath":"202309/20230816 How to Extend Veritas File System (VxFS) in Linux.md","filePath":"[post].md"}'),h={name:"202309/20230816 How to Extend Veritas File System (VxFS) in Linux.md"};function g(k,s,c,u,x,b){const i=d("Link");return p(),o("div",null,[s[24]||(s[24]=e("h1",{id:"如何在-linux-中擴展-veritas-文件系統-vxfs",tabindex:"-1"},[a("如何在 Linux 中擴展 Veritas 文件系統（VxFS） "),e("a",{class:"header-anchor",href:"#如何在-linux-中擴展-veritas-文件系統-vxfs","aria-label":"Permalink to “如何在 Linux 中擴展 Veritas 文件系統（VxFS）”"},"​")],-1)),s[25]||(s[25]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202309/17/095154jxqizcscc3xjuzrl.jpg",alt:""})],-1)),s[26]||(s[26]=e("p",null,"擴展 VxFX 文件系統是 Linux/Unix 管理員的一項日常任務，可以通過以下文章中描述的幾個步驟在線完成此任務：",-1)),s[27]||(s[27]=e("p",null,"在此，磁盤組沒有足夠的可用空間，因此我們將在現有磁盤組（DG）中添加新磁盤，然後調整其大小。",-1)),s[28]||(s[28]=e("p",null,[e("strong",null,"相關文章：")],-1)),e("ul",null,[e("li",null,[e("strong",null,[n(i,{href:"https://www.2daygeek.com/create-vxvm-volume-vxfs-filesystem-linux/"},{default:t(()=>[...s[0]||(s[0]=[a("如何在 Linux 中創建 VxVM 卷和文件系統",-1)])]),_:1})])]),e("li",null,[e("strong",null,[n(i,{href:"https://www.2daygeek.com/create-veritas-shared-vxfs-file-system-linux/"},{default:t(()=>[...s[1]||(s[1]=[a("如何在 Linux 上創建共享 VxFS 文件系統",-1)])]),_:1})])])]),s[29]||(s[29]=e("h3",{id:"步驟-1-識別文件系統",tabindex:"-1"},[a("步驟 1：識別文件系統 "),e("a",{class:"header-anchor",href:"#步驟-1-識別文件系統","aria-label":"Permalink to “步驟 1：識別文件系統”"},"​")],-1)),e("p",null,[s[3]||(s[3]=a("使用 ",-1)),n(i,{href:"https://www.2daygeek.com/linux-check-disk-space-usage-df-command/"},{default:t(()=>[...s[2]||(s[2]=[a("df 命令",-1)])]),_:1}),s[4]||(s[4]=a(" 檢查要增加/擴展的文件系統，並記下以下輸出中的磁盤組（DG）和卷名稱，稍後在運行 ",-1)),s[5]||(s[5]=e("code",null,"vxdg",-1)),s[6]||(s[6]=a(" 和 ",-1)),s[7]||(s[7]=e("code",null,"vxresize",-1)),s[8]||(s[8]=a(" 命令時將使用這些名稱。",-1))]),s[30]||(s[30]=r(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># df -hP /data</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Filesystem                  Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/vx/dsk/testdg/testvol  9.0G  8.4G 0.6G  95%  /data</span></span></code></pre></div><p>根據上面的輸出，VxFS 文件系統大小為 9.0 GB，我們希望額外擴展 5 GB 併發布此活動，VxFS 大小將為 14 GB。</p><p>在本例中，DG 名稱為 <code>testdg</code>，卷名稱為 <code>testvol</code>。</p><h3 id="步驟-2-獲取新磁盤-lun" tabindex="-1">步驟 2：獲取新磁盤/LUN <a class="header-anchor" href="#步驟-2-獲取新磁盤-lun" aria-label="Permalink to “步驟 2：獲取新磁盤/LUN”">​</a></h3><p>新磁盤必須由存儲團隊映射到主機，這可能需要 CR 批准，因此提出 CR 並向相關團隊添加必要的任務，並且還包括此活動的回滾計劃。</p><h3 id="步驟-3-掃描磁盤-lun" tabindex="-1">步驟 3：掃描磁盤/LUN <a class="header-anchor" href="#步驟-3-掃描磁盤-lun" aria-label="Permalink to “步驟 3：掃描磁盤/LUN”">​</a></h3><p>存儲團隊將新 LUN 映射到主機後，獲取 LUN id 並將其保存。</p><p>使用以下命令掃描 LUN 以在操作系統級別發現它們。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for disk_scan in \`ls /sys/class/scsi_host\`; do </span></span>
<span class="line"><span>    echo &quot;Scanning $disk_scan…Completed&quot;</span></span>
<span class="line"><span>    echo &quot;- - -&quot; &gt; /sys/class/scsi_host/$disk_scan/scan</span></span>
<span class="line"><span>done</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Scanning host0...Completed</span></span>
<span class="line"><span>Scanning host1...Completed</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>Scanning host[N]...Completed</span></span></code></pre></div><p>掃描完成後，使用以下命令查看是否在操作系統級別找到給定的 LUN。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lsscsi --scsi | grep -i [Last_Five_Digit_of_LUN]</span></span></code></pre></div><h3 id="步驟-4-在-vxvm-中查找磁盤" tabindex="-1">步驟 4：在 VxVM 中查找磁盤 <a class="header-anchor" href="#步驟-4-在-vxvm-中查找磁盤" aria-label="Permalink to “步驟 4：在 VxVM 中查找磁盤”">​</a></h3><p>默認情況下，所有可用磁盤對 Veritas 卷管理器（VxVM）都是可見的，可以使用 <code>vxdisk</code> 命令列出這些磁盤，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vxdisk -e list</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DEVICE       TYPE           DISK        GROUP        STATUS               OS_NATIVE_NAME   ATTR</span></span>
<span class="line"><span>emc_01       auto:cdsdisk   disk1       testdg       online               sdd              -</span></span>
<span class="line"><span>emc_02       auto:cdsdisk   disk2       testdg       online               sde              -</span></span>
<span class="line"><span>emc_03       auto:none      -           -            online invalid       sdf              -</span></span>
<span class="line"><span>sda          auto:LVM       -           -            LVM                  sda              -</span></span>
<span class="line"><span>sdb          auto:LVM       -           -            LVM                  sdb              -</span></span></code></pre></div><p>磁盤 <code>sdf</code> 的狀態顯示為 <code>Online invalid</code> 表示該磁盤不受 VxVM 控制。但是，請使用 <code>smartctl</code> 命令仔細檢查 LUN id，以確保你選擇了正確的磁盤。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>smartctl -a /dev/sd[x]|grep -i unit</span></span></code></pre></div><p>如果磁盤未填充到 VxVM，請執行以下命令掃描操作系統設備樹中的磁盤設備。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vxdisk scandisks</span></span></code></pre></div><h3 id="步驟-5-在-vxvm-中初始化磁盤" tabindex="-1">步驟 5：在 VxVM 中初始化磁盤 <a class="header-anchor" href="#步驟-5-在-vxvm-中初始化磁盤" aria-label="Permalink to “步驟 5：在 VxVM 中初始化磁盤”">​</a></h3><p>當磁盤在<strong>步驟 4</strong> 中對 VxVM 可見，那麼使用 <code>vxdisksetup</code> 命令初始化磁盤，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vxdisksetup -i sdf</span></span></code></pre></div><p>上面的命令將磁盤 <code>sdf</code> 帶到 Veritas 卷管理器（VxVM），並且磁盤狀態現在更改為 <code>online</code>。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2023/07/extend-increase-vxvm-volume-vxfs-filesystem-linux-1024x201.jpg" alt=""></p><h3 id="步驟-6-將磁盤添加到-vxvm-中的磁盤組-dg" tabindex="-1">步驟 6：將磁盤添加到 VxVM 中的磁盤組（DG） <a class="header-anchor" href="#步驟-6-將磁盤添加到-vxvm-中的磁盤組-dg" aria-label="Permalink to “步驟 6：將磁盤添加到 VxVM 中的磁盤組（DG）”">​</a></h3><p><code>vxdg</code> 命令對磁盤組執行各種管理操作。在此示例中，我們將使用它向現有磁盤組（DG）添加新磁盤。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vxdg -g [DG_Name] adddisk [Any_Name_to_Disk_as_per_Your_Wish=Device_Name]</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vxdg -g testdg adddisk disk3=emc_03</span></span></code></pre></div><p>運行上述命令後，磁盤名稱為 <code>disk3</code> 且磁盤組名稱為 <code>testdg</code> 已針對 <code>emc_03</code> 設備進行更新 如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vxdisk -e list</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DEVICE       TYPE           DISK        GROUP        STATUS               OS_NATIVE_NAME   ATTR</span></span>
<span class="line"><span>emc_01       auto:cdsdisk   disk1       testdg       online               sdd              -</span></span>
<span class="line"><span>emc_02       auto:cdsdisk   disk2       testdg       online               sde              -</span></span>
<span class="line"><span>emc_03       auto:none      disk3       testdg       online               sdf              -</span></span>
<span class="line"><span>sda          auto:LVM       -           -            LVM                  sda              -</span></span>
<span class="line"><span>sdb          auto:LVM       -           -            LVM                  sdb              -</span></span></code></pre></div><h3 id="步驟-7-檢查磁盤組-dg-中的可用空間" tabindex="-1">步驟 7：檢查磁盤組（DG）中的可用空間 <a class="header-anchor" href="#步驟-7-檢查磁盤組-dg-中的可用空間" aria-label="Permalink to “步驟 7：檢查磁盤組（DG）中的可用空間”">​</a></h3><p>要確定連接卷有多少可用空間，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vxassist -g testdg maxsize</span></span></code></pre></div><h3 id="步驟-8-擴展-vxvm-卷和-vxfs-文件系統" tabindex="-1">步驟 8：擴展 VxVM 卷和 VxFS 文件系統 <a class="header-anchor" href="#步驟-8-擴展-vxvm-卷和-vxfs-文件系統" aria-label="Permalink to “步驟 8：擴展 VxVM 卷和 VxFS 文件系統”">​</a></h3><p>我們為此活動添加了 5GB LUN，因此額外擴展了 VxVM 卷和 VxFS 文件系統 <code>5GB</code>，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vxresize -b -g [DG_Name] [Volume_Name] +[Size_to_be_Increased]</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vxresize -b -g testdg testvol +5g</span></span></code></pre></div><p>這裏：</p><ul><li><code>vxresize</code>：命令</li><li><code>-b</code>：在後台執行調整大小操作（可選）。</li><li><code>-g</code>：將命令的操作限制為給定磁盤組，由磁盤組 ID 或磁盤組名稱指定。</li><li><code>testdg</code>：我們的磁盤組（DG）名稱</li><li><code>test</code>vol\`：我們的卷名稱</li><li><code>+5g</code>：此卷將額外增加 5GB。</li></ul><h3 id="步驟-9-檢查擴展-vxfs-文件系統" tabindex="-1">步驟 9：檢查擴展 VxFS 文件系統 <a class="header-anchor" href="#步驟-9-檢查擴展-vxfs-文件系統" aria-label="Permalink to “步驟 9：檢查擴展 VxFS 文件系統”">​</a></h3><p>最後，使用 <code>df</code> 命令檢查 <code>/data</code> 的擴展 VxFS：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># df -hP /data</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Filesystem                  Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/vx/dsk/testdg/testvol  14G   8.4G 5.6G  68%  /data</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在本教程中，我們向你展示瞭如何向現有磁盤組（DG）添加新磁盤，以及如何通過幾個簡單步驟在 Linux 中擴展 VxVM 卷和 VxFS 文件系統。</p><p>如果你有任何問題或反饋，請隨時在下面發表評論。</p><p><em>（題圖：MJ/3fe4fdb7-99da-4b8f-a818-0ae232e6fbcc）</em></p><hr>`,47)),e("p",null,[s[10]||(s[10]=a("via: ",-1)),n(i,{href:"https://www.2daygeek.com/extend-increase-vxvm-volume-vxfs-filesystem-linux/"},{default:t(()=>[...s[9]||(s[9]=[a("https://www.2daygeek.com/extend-increase-vxvm-volume-vxfs-filesystem-linux/",-1)])]),_:1})]),e("p",null,[s[15]||(s[15]=a("作者：",-1)),n(i,{href:"https://www.2daygeek.com/author/jayabal/"},{default:t(()=>[...s[11]||(s[11]=[a("Jayabal Thiyagarajan",-1)])]),_:1}),s[16]||(s[16]=a(" 選題：",-1)),n(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[12]||(s[12]=[a("lujun9972",-1)])]),_:1}),s[17]||(s[17]=a(" 譯者：",-1)),n(i,{href:"https://github.com/geekpi"},{default:t(()=>[...s[13]||(s[13]=[a("geekpi",-1)])]),_:1}),s[18]||(s[18]=a(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[21]||(s[21]=a("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原創編譯，",-1)),n(i,{href:"https://linux.cn/"},{default:t(()=>[...s[20]||(s[20]=[a("Linux中國",-1)])]),_:1}),s[23]||(s[23]=a(" 榮譽推出",-1))])])}const V=l(h,[["render",g]]);export{v as __pageData,V as default};
